#!/usr/bin/env python3
"""sen0414_lineage_cancel_ch08repair v1_0_0 - cancels the held page repair of chapter 8 (ST_CI5_Page_Ch08 with TK_CI5_Page_Ch08_Repair and its Verify) as SUPERSEDED, through the change route
(ChangeRequest, ImpactAssessment with the as-is fit-gap and the closure statement, withdraw transitions). The coordinator's direction of 2026-11-01 (no owner question: gaps are handled through change management)."""
__version__ = "1.0.0"
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
lit = W.lit
def main():
    src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now()
    why = ("SUPERSEDED. AS-IS FIT-GAP (measured 2026-10-30 and 2026-11-01 by the lineage agent): the repair asked for a NEW page of chapter 8 that restores the warnings state after every program (page v9_91_0). ACCOMPLISHED: page v9_91_0 exists (committed), and the urgent Chapter 8 work then produced page v9_92_1 on template 9.53.1 "
           "(page test 9.38.0 run 1 PASS with 418 features passed and 0 failed; diagram audit, Playground width probe and story-layout probe PASS; controlled on the lineage agent's own runs in register 2.337.0 and after), which contains v9_91_0's content and the warnings repair and adds full screen, a resizable panel, the deck's code as one tab in slide order and no lambda. "
           "FAILED: nothing the repair asked for remains unmet. IN PROGRESS: the repair task was started 2026-10-29T13:02:52, then held by the urgent interruption of 2026-10-30 and left unresumed; no executor works on it. DUE: nothing; the work it would still do (a page built on template 9.52.4) would produce a page older than v9_92_1 and would have to be thrown away. "
           "CLOSURE REPORT: the story and its tasks end CANCELLED (superseded by ex:ST_U8_Page, page v9_92_1); the objective Obj2_StdPages is not moved by this story, and v9_92_1 is counted by the urgent story. No gate is weakened and nothing is waived: the controls the repair's Verify task would have run (page test 9.37.0, probes, chapter check) are run on v9_92_1 by the urgent story's verification.")
    cr = ('\nex:CR2_Cancel_Ch08Repair a backlog:ChangeRequest ; rdfs:label "Cancel the held repair of the Chapter 8 page as superseded by page v9.92.1"@en ;\n    backlog:requestsChangeTo ex:Scope2 ; backlog:hasChangeDirection backlog:Direction_Shrink ;\n'
          '    backlog:hasChangeRequestRationale %s ;\n    backlog:hasDisposition backlog:Disp_Accepted .\n') % lit("Direction of the course coordinator, 2026-11-01: cancel the held repair TK_CI5_Page_Ch08_Repair, superseded in substance by page v9.92.1, through the change route with the as-is fit-gap and the closure report; no owner question is needed (gaps are handled through change management). " + why)
    ia = ('\nex:IA2_Cancel_Ch08Repair a backlog:ImpactAssessment ; rdfs:label "What cancelling the held Chapter 8 page repair changes"@en ;\n    backlog:analyzesRequest ex:CR2_Cancel_Ch08Repair ; backlog:identifiesAffectedLineage ex:Lineage2 ;\n    backlog:hasImpactStatement %s .\n') % lit(why + " WHAT MOVES: three items go to Cancelled with a rationale: ex:TK_CI5_Page_Ch08_Repair (InProgress, resumed after the earlier interruption), ex:TK_CI5_Page_Ch08_Repair_Verify (Ready) and ex:ST_CI5_Page_Ch08 (InProgress). Nothing else changes; the scope does not shrink in deliverables (the Chapter 8 page deliverable is met by v9_92_1).")
    sc = 'ex:SC2_Cancel_Ch08Repair a backlog:ScopeChange ; rdfs:label "Cancellation of the held Chapter 8 page repair recorded as a shrink of the scope"@en ;\n    backlog:fulfillsRequest ex:CR2_Cancel_Ch08Repair ; backlog:changesScope ex:Scope2 ; backlog:decidedBy backlog:Owner ;\n    backlog:admitsItem ex:ST_U8_Page ;\n    backlog:hasScopeChangeRationale %s .\nex:CR2_Cancel_Ch08Repair rdfs:comment "Disposition Accepted on the coordinator\'s direction of 2026-11-01 (gaps are handled through change management; the owner is not asked); the ScopeChange ex:SC2_Cancel_Ch08Repair records what it left behind."@en .\n' % lit('The three items ex:ST_CI5_Page_Ch08, ex:TK_CI5_Page_Ch08_Repair and ex:TK_CI5_Page_Ch08_Repair_Verify leave the scope as Cancelled (superseded by page v9_92_1); the deliverables are unchanged. ' + why[:500])
    out = [cr, ia, sc]
    for k, via, frm in (("TK_CI5_Page_Ch08_Repair", "T_WithdrawInProgress", "InProgress"), ("TK_CI5_Page_Ch08_Repair_Verify", "T_WithdrawReady", "Ready"), ("ST_CI5_Page_Ch08", "T_WithdrawInProgress", "InProgress")):
        m = re.search(r"\nex:%s a backlog:\w+ ;.*?\n(?=ex:|\n)" % re.escape(k), t, re.S); assert m, k
        i = t.index("\nex:%s a backlog:" % k) + 1; j = t.find("\nex:", i); b = t[i:j]
        assert "backlog:hasState backlog:%s" % frm in b, (k, frm)
        t = t[:i] + b.replace("backlog:hasState backlog:%s" % frm, "backlog:hasState backlog:Cancelled ; backlog:hasRationale %s" % lit("Cancelled " + now + " UTC by the change route ex:CR2_Cancel_Ch08Repair: superseded by page v9_92_1. " + why[:600]), 1) + t[j:]
        out.append('ex:Cancel_%s a backlog:TransitionEvent ; rdfs:label "%s cancelled as superseded"@en ; backlog:transitionedItem ex:%s ;\n    backlog:viaTransition backlog:%s ; backlog:transitionedAt "%s"^^xsd:dateTime ; backlog:transitionedBy backlog:Builder ;\n    backlog:hasTransitionNote %s .\n' % (k, k, k, via, now + "Z", lit("Cancelled by the change route ex:CR2_Cancel_Ch08Repair; see ex:IA2_Cancel_Ch08Repair for the as-is fit-gap and the closure statement.")))
    print(os.path.basename(W.write_new(src, t + "\n" + "\n".join(out), "Held Chapter 8 page repair (ST_CI5_Page_Ch08, TK_CI5_Page_Ch08_Repair and its Verify) cancelled as superseded by page v9_92_1, through ChangeRequest ex:CR2_Cancel_Ch08Repair and ImpactAssessment ex:IA2_Cancel_Ch08Repair with the as-is fit-gap and closure statement.")))
main()
